import math


def extract_delivery_cost(payload):
    if not isinstance(payload, dict):
        raise ValueError("payload must be a dictionary")
    ok = payload.get("ok")
    if not isinstance(ok, bool):
        raise ValueError("ok must be a boolean")
    if not ok:
        return None
    result = payload.get("result")
    if not isinstance(result, dict) or "cost" not in result:
        raise ValueError("missing result cost")
    cost = result["cost"]
    if not cost or isinstance(cost, bool) or not isinstance(cost, (int, float)) or not math.isfinite(cost) or cost < 0:
        raise ValueError("invalid cost")
    return cost

